// Reads the ceiling and holds the row until the transaction ends, so an org's level and a lowering
// of the ceiling cannot pass each other.
func (q *Queries) LockPlatformTraceSettings(ctx context.Context) (PlatformTraceSetting, error) {
	row := q.db.QueryRow(ctx, lockPlatformTraceSettings)
	var i PlatformTraceSetting
	err := row.Scan(
		&i.Singleton,
		&i.ContentCeiling,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}

const lowerOrgTraceLevels = `-- name: LowerOrgTraceLevels :many
WITH before AS (
    SELECT org_id, content_level AS old_level, platform_copy_level AS old_copy_level
    FROM org_trace_settings
    WHERE content_level > $1::trace_content_level
    ORDER BY org_id
    FOR UPDATE
), changed AS (
    UPDATE org_trace_settings s
    SET content_level = $1::trace_content_level,
        platform_copy_level = LEAST(s.platform_copy_level, $1::trace_content_level),
        updated_by = $2
    FROM before b
    WHERE s.org_id = b.org_id
    RETURNING s.org_id
)
SELECT b.org_id, b.old_level, b.old_copy_level
FROM before b
JOIN changed c ON c.org_id = b.org_id
ORDER BY b.org_id
`

type LowerOrgTraceLevelsParams struct {
	Ceiling   TraceContentLevel
	UpdatedBy string
}

type LowerOrgTraceLevelsRow struct {
	OrgID        pgtype.UUID
	OldLevel     TraceContentLevel
	OldCopyLevel TraceContentLevel
}

// Lowers every org above a new platform ceiling to it, and the platform copies that follow, in the
// caller's transaction. Returns the orgs it changed with their levels before, for the audit log, in org ID
// order: the ORDER BY stays for the row locks, which are taken in that order. The audit batch orders the
// events it writes (ADR 0100 decision 1.7), so the caller does not depend on this order.
func (q *Queries) LowerOrgTraceLevels(ctx context.Context, arg LowerOrgTraceLevelsParams) ([]LowerOrgTraceLevelsRow, error) {
	rows, err := q.db.Query(ctx, lowerOrgTraceLevels, arg.Ceiling, arg.UpdatedBy)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LowerOrgTraceLevelsRow
	for rows.Next() {
		var i LowerOrgTraceLevelsRow
		if err := rows.Scan(&i.OrgID, &i.OldLevel, &i.OldCopyLevel); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

